import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Stethoscope, ArrowRight } from 'lucide-react';
import { Button } from '../components/UI';

export default function LandingPage() {
  const navigate = useNavigate();

  return (
    <div style={styles.container}>
      <div style={styles.content}>
        {/* Logo/Brand */}
        <div style={styles.logo}>
          <Stethoscope size={48} color="var(--teal)" />
          <h1 style={styles.brandName}>MediBook</h1>
        </div>

        {/* Hero Section */}
        <div style={styles.hero}>
          <h2 style={styles.heroTitle}>Your Health, Booked</h2>
          <p style={styles.heroSubtitle}>
            Book appointments with top healthcare providers. Simple, fast, and secure.
          </p>
        </div>

        {/* CTA Buttons */}
        <div style={styles.ctaContainer}>
          <Button
            variant="dark"
            size="lg"
            onClick={() => navigate('/login')}
            style={styles.ctaButton}
          >
            Login <ArrowRight size={18} style={{ marginLeft: 8 }} />
          </Button>
          <Button
            variant="outline"
            size="lg"
            onClick={() => navigate('/signup')}
            style={styles.ctaButton}
          >
            Sign Up <ArrowRight size={18} style={{ marginLeft: 8 }} />
          </Button>
        </div>

        {/* Features */}
        <div style={styles.features}>
          {[
            'Easy Appointment Booking',
            'Verified Healthcare Providers',
            'Secure Medical Records',
            '24/7 Appointment Management'
          ].map((feature, index) => (
            <div key={index} style={styles.feature}>
              <div style={styles.featureDot} />
              <span style={styles.featureText}>{feature}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Background decoration */}
      <div style={styles.bgCircle1} />
      <div style={styles.bgCircle2} />
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'linear-gradient(135deg, #f5f7fa 0%, #e4e8ec 100%)',
    position: 'relative',
    overflow: 'hidden',
    padding: '20px',
  },
  content: {
    background: '#fff',
    borderRadius: 24,
    padding: '60px 48px',
    maxWidth: 520,
    width: '100%',
    boxShadow: '0 20px 60px rgba(0, 0, 0, 0.1)',
    position: 'relative',
    zIndex: 1,
  },
  logo: {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    marginBottom: 32,
    justifyContent: 'center',
  },
  brandName: {
    fontFamily: 'var(--font-display)',
    fontSize: '2rem',
    fontWeight: 700,
    color: 'var(--ink)',
    margin: 0,
  },
  hero: {
    textAlign: 'center',
    marginBottom: 40,
  },
  heroTitle: {
    fontFamily: 'var(--font-display)',
    fontSize: '2.5rem',
    fontWeight: 700,
    color: 'var(--ink)',
    marginBottom: 12,
    lineHeight: 1.2,
  },
  heroSubtitle: {
    fontSize: '1rem',
    color: 'var(--text-muted)',
    lineHeight: 1.6,
    margin: 0,
  },
  ctaContainer: {
    display: 'flex',
    flexDirection: 'column',
    gap: 14,
    marginBottom: 40,
  },
  ctaButton: {
    width: '100%',
    padding: '14px 24px',
    fontSize: '1rem',
    fontWeight: 600,
  },
  features: {
    display: 'flex',
    flexDirection: 'column',
    gap: 12,
  },
  feature: {
    display: 'flex',
    alignItems: 'center',
    gap: 10,
  },
  featureDot: {
    width: 8,
    height: 8,
    borderRadius: '50%',
    background: 'var(--teal)',
    flexShrink: 0,
  },
  featureText: {
    fontSize: '0.9rem',
    color: 'var(--text-muted)',
  },
  bgCircle1: {
    position: 'absolute',
    width: 400,
    height: 400,
    borderRadius: '50%',
    background: 'rgba(0, 181, 163, 0.08)',
    top: -200,
    right: -100,
    zIndex: 0,
  },
  bgCircle2: {
    position: 'absolute',
    width: 300,
    height: 300,
    borderRadius: '50%',
    background: 'rgba(0, 181, 163, 0.05)',
    bottom: -100,
    left: -100,
    zIndex: 0,
  },
};
